#include <bits/stdc++.h>
using namespace std;

long long clc(long long a,long long b,vector<long long>&arr1,long long n){
    long long used=3*n-2*a-b;
    return 2*arr1[a]+arr1[a+2*b]+3*arr1[used];
}

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    long long n;
	    cin>>n;
	    int tot=3*n;
	    vector<long long>arr(tot+1,0);
	    for(int i=1;i<=tot;i++){
	        cin>>arr[i];
	    }
	    sort(arr.begin()+1,arr.end(),greater<long long>());
	    vector<long long>arr2(tot+1,0);
	    for(int i=1;i<=tot;i++)arr2[i]=arr2[i-1]+arr[i];
	    long long maxi=0;
	    for(long long i=0;i<=n;i++){
	        long long low=0,high=n-i;
	        while(high-low>2){
	            long long x1=low+(high-low)/3;
	            long long x2=high-(high-low)/3;
	            long long val1=clc(i,x1,arr2,n);
	            long long val2=clc(i,x2,arr2,n);
	            if(val1<val2)low=x1;
	            else if(val1>val2)high=x2;
	            else{
	                low=x1;
	                high=x2;
	            }
	        }
	        for(long long j=low;j<=high;j++){
	            maxi=max(maxi,clc(i,j,arr2,n));
	        }
	    }
	    cout<<maxi<<endl;
	}
}
